BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
DO $guard$ BEGIN IF (SELECT array_agg(c.relname::text ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p','v','m','f')) IS DISTINCT FROM ARRAY['auditoria','categoria','cotacao','fornecedor','lote','movimento_estoque','perfil','prato','produto','refeicao_servida','unidade_medida','unidade_restaurante','usuario','usuario_unidade']::text[] THEN RAISE EXCEPTION 'Tabelas public divergentes'; END IF;
    IF COALESCE((SELECT array_agg(c.relname::text ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S'),ARRAY[]::text[]) IS DISTINCT FROM ARRAY['auditoria_id_auditoria_seq','categoria_id_categoria_seq','cotacao_id_cotacao_seq','fornecedor_id_fornecedor_seq','lote_id_lote_seq','movimento_estoque_id_movimento_seq','perfil_id_perfil_seq','prato_id_prato_seq','produto_id_produto_seq','refeicao_servida_id_refeicao_servida_seq','unidade_medida_id_unidade_medida_seq','unidade_restaurante_id_unidade_seq']::text[] THEN RAISE EXCEPTION 'Sequências public divergentes'; END IF;
    IF EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public') THEN RAISE EXCEPTION 'Políticas public divergentes'; END IF;
    IF EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND a.attacl IS NOT NULL) THEN RAISE EXCEPTION 'ACL de coluna não suportada'; END IF;
    IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public') THEN RAISE EXCEPTION 'Funções public não suportadas'; END IF; END $guard$;
LOCK TABLE public."auditoria", public."categoria", public."cotacao", public."fornecedor", public."lote", public."movimento_estoque", public."perfil", public."prato", public."produto", public."refeicao_servida", public."unidade_medida", public."unidade_restaurante", public."usuario", public."usuario_unidade" IN ACCESS EXCLUSIVE MODE;
DO $guard$ BEGIN IF EXISTS(SELECT 1 FROM public."auditoria") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."categoria") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."cotacao") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."fornecedor") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."lote") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."movimento_estoque") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."perfil") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."prato") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."produto") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."refeicao_servida") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."unidade_medida") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."unidade_restaurante") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."usuario") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF;
IF EXISTS(SELECT 1 FROM public."usuario_unidade") THEN RAISE EXCEPTION 'Tabela não vazia'; END IF; END $guard$;
ALTER TABLE public."auditoria" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."categoria" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."cotacao" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."fornecedor" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."lote" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."movimento_estoque" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."perfil" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."prato" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."produto" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."refeicao_servida" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."unidade_medida" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."unidade_restaurante" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."usuario" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."usuario_unidade" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM anon, authenticated, PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM anon, authenticated, PUBLIC;
COMMIT;
